-- ============================================================
-- Sistem Rental Mobil - PHP Native + MySQL
-- Import file ini lewat phpMyAdmin atau:
--   mysql -u root -p < database/rental_mobil.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS rental_mobil CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rental_mobil;

DROP TABLE IF EXISTS sewa;
DROP TABLE IF EXISTS mobil;
DROP TABLE IF EXISTS pelanggan;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','petugas') NOT NULL DEFAULT 'petugas',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_usaha VARCHAR(100) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  denda_per_hari_persen INT NOT NULL DEFAULT 120,
  biaya_sopir_per_hari INT NOT NULL DEFAULT 150000
) ENGINE=InnoDB;

CREATE TABLE mobil (
  id INT AUTO_INCREMENT PRIMARY KEY,
  plat_nomor VARCHAR(15) NOT NULL UNIQUE,
  merk VARCHAR(50) NOT NULL,
  model VARCHAR(50) NOT NULL,
  tahun YEAR NOT NULL,
  warna VARCHAR(30),
  kursi TINYINT NOT NULL DEFAULT 7,
  transmisi ENUM('Manual','Matic') NOT NULL DEFAULT 'Manual',
  bahan_bakar ENUM('Bensin','Solar','Listrik','Hybrid') NOT NULL DEFAULT 'Bensin',
  harga_per_hari INT NOT NULL,
  status ENUM('tersedia','disewa','servis') NOT NULL DEFAULT 'tersedia',
  foto VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE pelanggan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nik VARCHAR(20) NOT NULL UNIQUE,
  nama VARCHAR(100) NOT NULL,
  telepon VARCHAR(20) NOT NULL,
  alamat TEXT,
  no_sim VARCHAR(20),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE sewa (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  pelanggan_id INT NOT NULL,
  mobil_id INT NOT NULL,
  user_id INT,
  tgl_mulai DATE NOT NULL,
  tgl_selesai DATE NOT NULL,
  tgl_kembali DATE NULL,
  lama_hari INT NOT NULL,
  harga_per_hari INT NOT NULL,
  pakai_sopir TINYINT(1) NOT NULL DEFAULT 0,
  biaya_sopir INT NOT NULL DEFAULT 0,
  subtotal INT NOT NULL,
  denda INT NOT NULL DEFAULT 0,
  total INT NOT NULL,
  dibayar INT NOT NULL DEFAULT 0,
  status ENUM('berjalan','selesai','batal') NOT NULL DEFAULT 'berjalan',
  catatan TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (pelanggan_id) REFERENCES pelanggan(id),
  FOREIGN KEY (mobil_id) REFERENCES mobil(id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

